"""Procedural surface painting for Ragini (numpy only - no images are generated by AI or downloaded here, except the
real photographed fabric/wood scans passed in by the build when they are available).

* raster()        UV-space rasteriser: for every texel of a UV layout, the 3D point and normal it shows
* skin()          her skin: ashen and blotched, veins, kajal running from the eyes, blood from the mouth, the
                  red bindi, the blouse with its gold edging, black nails, dirty soles, the dark mouth
* fabric()        the saree cloth: deep red silk with a gold temple border, stains and wear
* eye(), scale_tex(), hair (see hair.texture)
"""
import math

import numpy as np


# ------------------------------------------------------------------------------------------------ noise
def _hash(ix, iy, iz, seed):
    h = (ix * 73856093) ^ (iy * 19349663) ^ (iz * 83492791) ^ (seed * 2654435761)
    h = (h ^ (h >> 13)) * 1274126177
    h = h ^ (h >> 16)
    return (h & 0xFFFFFF).astype(np.float64) / float(0xFFFFFF)


def vnoise(P, freq, seed=0):
    """Smooth value noise in 3D, range 0..1."""
    q = np.asarray(P, float) * freq
    i = np.floor(q).astype(np.int64)
    f = q - i
    f = f * f * (3 - 2 * f)
    out = 0.0
    for dx in (0, 1):
        for dy in (0, 1):
            for dz in (0, 1):
                w = (f[:, 0] if dx else 1 - f[:, 0]) * (f[:, 1] if dy else 1 - f[:, 1]) * (f[:, 2] if dz else 1 - f[:, 2])
                out = out + w * _hash(i[:, 0] + dx, i[:, 1] + dy, i[:, 2] + dz, seed)
    return out


def fbm(P, freq, octaves=4, seed=0, gain=0.5):
    a, tot, out = 1.0, 0.0, 0.0
    for o in range(octaves):
        out = out + a * vnoise(P, freq * (2.03 ** o), seed + o * 17)
        tot += a
        a *= gain
    return out / tot


def ridged(P, freq, octaves=3, seed=0):
    """Thin dark lines (veins, cracks): 1 on the ridge, 0 elsewhere."""
    v = 0.0
    a = 1.0
    for o in range(octaves):
        n = vnoise(P, freq * (2.1 ** o), seed + 31 * o)
        v = np.maximum(v, a * (1.0 - np.abs(2.0 * n - 1.0)) ** 8)
        a *= 0.7
    return v


def smooth(e0, e1, x):
    t = np.clip((x - e0) / (e1 - e0), 0.0, 1.0)
    return t * t * (3 - 2 * t)


def mix(a, b, t):
    t = np.asarray(t, float)
    if t.ndim == 1 and np.ndim(a) == 2:
        t = t[:, None]
    return a * (1 - t) + b * t


# ------------------------------------------------------------------------------------------------ rasteriser
def raster(uv, tris, verts, nrms, size):
    """For a UV layout (per-corner uv (M, 3, 2) or per-vertex), return position, normal and coverage maps.
    uv: (n_corners, 2) indexed like tris.ravel(); verts/nrms per vertex."""
    W = H = size
    pos = np.zeros((H, W, 3))
    nor = np.zeros((H, W, 3))
    cov = np.zeros((H, W), bool)
    UVt = uv.reshape(-1, 3, 2) * np.array([W, H]) - 0.5
    for k in range(len(tris)):
        a, b, c = UVt[k]
        x0, x1 = int(max(0, math.floor(min(a[0], b[0], c[0])))), int(min(W - 1, math.ceil(max(a[0], b[0], c[0]))))
        y0, y1 = int(max(0, math.floor(min(a[1], b[1], c[1])))), int(min(H - 1, math.ceil(max(a[1], b[1], c[1]))))
        if x1 < x0 or y1 < y0:
            continue
        xs, ys = np.meshgrid(np.arange(x0, x1 + 1), np.arange(y0, y1 + 1))
        px = xs.ravel().astype(float)
        py = ys.ravel().astype(float)
        d = (b[1] - c[1]) * (a[0] - c[0]) + (c[0] - b[0]) * (a[1] - c[1])
        if abs(d) < 1e-12:
            continue
        l1 = ((b[1] - c[1]) * (px - c[0]) + (c[0] - b[0]) * (py - c[1])) / d
        l2 = ((c[1] - a[1]) * (px - c[0]) + (a[0] - c[0]) * (py - c[1])) / d
        l3 = 1 - l1 - l2
        m = (l1 >= -0.02) & (l2 >= -0.02) & (l3 >= -0.02)
        if not m.any():
            continue
        t = tris[k]
        L = np.stack([l1[m], l2[m], l3[m]], 1)
        L = np.clip(L, 0, None)
        L /= L.sum(axis=1, keepdims=True)
        yy, xx = ys.ravel()[m], xs.ravel()[m]
        pos[yy, xx] = L @ verts[t]
        nor[yy, xx] = L @ nrms[t]
        cov[yy, xx] = True
    n = np.linalg.norm(nor, axis=2, keepdims=True)
    nor = np.where(n > 1e-9, nor / np.maximum(n, 1e-9), 0)
    return pos, nor, cov


def dilate(img, cov, steps=8):
    """Grow covered texels into the gutter so texture filtering never pulls in the background."""
    img = img.copy()
    cov = cov.copy()
    for _ in range(steps):
        acc = np.zeros_like(img)
        cnt = np.zeros(cov.shape)
        for dy, dx in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            sc = np.roll(np.roll(cov, dy, 0), dx, 1)
            si = np.roll(np.roll(img, dy, 0), dx, 1)
            acc += si * sc[..., None]
            cnt += sc
        grow = (~cov) & (cnt > 0)
        img[grow] = acc[grow] / cnt[grow][:, None]
        cov = cov | grow
    return img


# ------------------------------------------------------------------------------------------------ skin
SKIN = np.array([0.56, 0.55, 0.52])          # ashen, bloodless
SKIN_DARK = np.array([0.30, 0.31, 0.30])
BLOUSE = np.array([0.30, 0.018, 0.025])
GOLD = np.array([0.62, 0.43, 0.12])
BLOOD = np.array([0.20, 0.008, 0.006])
BLOOD_DRY = np.array([0.13, 0.03, 0.02])
NAIL = np.array([0.035, 0.03, 0.028])
HAIR = np.array([0.025, 0.022, 0.02])
SINDOOR = np.array([0.62, 0.04, 0.02])


def skin(P, N, marks, eye_c=None):
    """Albedo (n, 3) and roughness (n,) for points on her skin."""
    n = len(P)
    x, y, z = P[:, 0], P[:, 1], P[:, 2]
    col = np.tile(SKIN, (n, 1))
    blot = fbm(P, 9.0, 4, seed=1)
    col = col * (0.82 + 0.3 * blot)[:, None]
    col = mix(col, col * np.array([0.86, 0.95, 0.9]), smooth(0.55, 0.8, fbm(P, 4.0, 3, seed=2)))      # greenish bruising
    # veins: dark blue-grey lines, strongest on the neck, temples, forearms
    vein = ridged(P, 38.0, 3, seed=5) * (0.4 + 0.6 * smooth(0.45, 0.7, fbm(P, 3.0, 2, seed=6)))
    col = mix(col, np.array([0.22, 0.25, 0.32]), vein * 0.55)
    rough = 0.62 + 0.15 * fbm(P, 30.0, 2, seed=9)
    # grime on hands, feet and knees
    grime = smooth(0.5, 0.8, fbm(P, 14.0, 3, seed=11)) * (0.4 + 0.6 * smooth(1.0, 0.2, z))
    col = mix(col, col * np.array([0.45, 0.4, 0.34]), grime * 0.6)
    # -------- face
    ex = eye_c if eye_c is not None else [np.array([0.03, -0.0745, 1.6025]), np.array([-0.03, -0.0745, 1.6025])]
    for e in ex:
        d = P - e
        r = np.sqrt((d[:, 0] / 1.15) ** 2 + (d[:, 2] / 0.9) ** 2)
        front = y < -0.05
        sock = smooth(0.026, 0.012, r) * front
        col = mix(col, np.array([0.05, 0.035, 0.04]), sock * 0.92)        # black, sunken sockets
        # kajal / tears running down the cheeks
        streak_x = np.abs(d[:, 0] + 0.002 * np.sin(z * 260.0))
        run = smooth(0.0045, 0.0015, streak_x) * smooth(0.0, -0.012, d[:, 2]) * smooth(-0.075, -0.03, d[:, 2]) * front
        col = mix(col, np.array([0.03, 0.025, 0.03]), run * 0.85)
    # lips: dark, bruised; inside of the mouth: deep red-black
    m = marks.get("mouth", np.array([0, -0.086, 1.508]))
    dm = P - m
    lip_r = np.sqrt((dm[:, 0] / 0.026) ** 2 + (dm[:, 2] / 0.026) ** 2)
    col = mix(col, np.array([0.16, 0.06, 0.07]), smooth(1.05, 0.75, lip_r) * (y < -0.06))
    inner = (y > -0.083) & (y < -0.02) & (lip_r < 0.85) & (np.abs(dm[:, 2]) < 0.022) & (np.abs(dm[:, 0]) < 0.022)
    col = mix(col, np.array([0.12, 0.012, 0.012]), inner.astype(float))
    # blood from the mouth down the chin and neck
    drip = np.zeros(n)
    rng = np.random.default_rng(3)
    for k in range(7):
        cx = rng.uniform(-0.018, 0.018)
        w = rng.uniform(0.002, 0.005)
        length = rng.uniform(0.04, 0.11)
        wig = 0.003 * np.sin(z * rng.uniform(150, 260) + k)
        lane = smooth(w, w * 0.3, np.abs(x - cx - wig)) * smooth(1.49, 1.485, z) * smooth(1.488 - length, 1.488 - length + 0.01, z)
        drip = np.maximum(drip, lane * (y < 0.0))
    chin = smooth(0.032, 0.012, np.sqrt(dm[:, 0] ** 2 + (dm[:, 2] + 0.02) ** 2)) * (y < -0.05)
    drip = np.maximum(drip, chin * 0.8)
    col = mix(col, BLOOD, drip * 0.9)
    rough = np.where(drip > 0.4, 0.3, rough)
    # red bindi
    bd = np.sqrt(x ** 2 + (z - 1.637) ** 2)
    col = mix(col, np.array([0.55, 0.01, 0.01]), smooth(0.0055, 0.0045, bd) * (y < -0.06))
    # scalp under the hair: black, the parting filled with sindoor
    scalp = smooth(1.655, 1.675, z) * (y < 0.08) + smooth(1.6, 1.62, z) * (y >= -0.02)
    scalp = np.clip(scalp, 0, 1) * (z > 1.57) * (np.abs(x) < 0.085)
    ear_zone = (np.abs(x) > 0.064) & (z < 1.61)
    scalp = scalp * ~ear_zone
    back = (y > 0.03) & (z > 1.5) & (np.abs(x) < 0.07)
    scalp = np.maximum(scalp, back * smooth(1.5, 1.53, z))
    col = mix(col, HAIR * (0.8 + 0.4 * fbm(P, 90.0, 2, seed=14))[:, None], scalp)
    part = smooth(0.0028, 0.001, np.abs(x)) * (z > 1.66) * (y < 0.06) * (y > -0.075)
    col = mix(col, SINDOOR, part)
    rough = np.where(scalp > 0.5, 0.75, rough)
    # -------- blouse: chest from under the bust to the neckline, short sleeves
    bb = marks.get("blouse_bottom", 1.168)
    torso = (np.abs(x) < 0.2) & (z > bb) & (z < 1.47)
    neck_front = (y < -0.0) & (z > 1.36 - 0.0 * x) & (np.abs(x) < 0.075 + (z - 1.36) * 0.6)
    neck_back = (y > 0.0) & (z > 1.40) & (np.abs(x) < 0.08)
    blouse = torso & ~neck_front & ~neck_back
    for side in ("L", "R"):
        se = marks.get("sleeve_end." + side)
        sh = marks.get("shoulder." + side)
        if se is None or sh is None:
            continue
        ax = se - sh
        L2 = float(ax @ ax)
        t = ((P - sh) @ ax) / L2
        rad = np.linalg.norm((P - sh) - np.outer(t, ax), axis=1)
        sleeve = (t > -0.4) & (t < 1.0) & (rad < 0.075)
        blouse = blouse | sleeve
        edge = (t > 0.9) & (t < 1.0) & (rad < 0.075)
        col = mix(col, GOLD, (blouse & edge).astype(float))
    hem = blouse & (z < bb + 0.012)
    weave = 0.85 + 0.15 * np.sin(x * 2200.0) * np.sin(z * 2000.0)
    bcol = BLOUSE * (weave * (0.75 + 0.5 * fbm(P, 25.0, 3, seed=20)))[:, None]
    bcol = mix(bcol, bcol * 0.4, smooth(0.6, 0.85, fbm(P, 8.0, 3, seed=21)))     # stains
    col = np.where(blouse[:, None], bcol, col)
    col = np.where(hem[:, None], GOLD * (0.8 + 0.3 * fbm(P, 60.0, 2, seed=22))[:, None], col)
    rough = np.where(blouse, 0.8, rough)
    # -------- nails and dirty soles
    nail_mask = np.zeros(n, bool)
    for side in ("L", "R"):
        for (tip, d) in marks.get("fingertips." + side, []):
            dd = P - tip
            along = dd @ d
            nail_mask |= (np.linalg.norm(dd, axis=1) < 0.017) & (along > -0.004)
    for side in ("L", "R"):
        for q in marks.get("toes." + side, []):
            nail_mask |= (np.linalg.norm(P - q, axis=1) < 0.009) & (z > q[2])
    col = np.where(nail_mask[:, None], NAIL, col)
    rough = np.where(nail_mask, 0.35, rough)
    sole = (z < 0.03)
    col = mix(col, np.array([0.12, 0.1, 0.08]), sole.astype(float) * 0.85)
    return np.clip(col, 0, 1), np.clip(rough, 0.05, 1.0)


# ------------------------------------------------------------------------------------------------ saree cloth
def temple_border(u, v, scale_u):
    """Gold zari border: two thin lines, a row of temple triangles, a band of small diamonds. v in metres from the edge."""
    gold = np.zeros_like(u)
    gold = np.maximum(gold, ((v > 0.004) & (v < 0.0075)).astype(float))
    gold = np.maximum(gold, ((v > 0.052) & (v < 0.055)).astype(float))
    # temple (gopuram) triangles between v = 0.011 and 0.040, pointing away from the edge
    period = 0.032
    fu = (u * scale_u / period) % 1.0
    hgt = 0.029 * (1.0 - np.abs(2 * fu - 1))
    tri = (v > 0.011) & (v < 0.011 + hgt)
    gold = np.maximum(gold, tri.astype(float))
    # small diamonds in the band 0.043..0.050
    fu2 = (u * scale_u / 0.012) % 1.0
    dia = (np.abs(2 * fu2 - 1) * 0.0035 + np.abs(v - 0.0465)) < 0.0032
    gold = np.maximum(gold, dia.astype(float))
    return gold


def fabric(Wpx, Hpx, len_u, len_v, weave=None, seed=0, border_edges=("v0",), pallu_end=False):
    """Saree texture for a cloth patch measuring len_u x len_v metres: (H, W, 3) albedo and (H, W) roughness.
    weave: optional photographed fabric (h, w, 3, 0..1) used for the cloth grain."""
    u = (np.arange(Wpx) + 0.5) / Wpx
    v = (np.arange(Hpx) + 0.5) / Hpx
    U, Vv = np.meshgrid(u, v)
    base = np.array([0.36, 0.018, 0.028])
    col = np.tile(base, (Hpx, Wpx, 1))
    if weave is not None:
        wh, ww = weave.shape[:2]
        # the photo tiles every 18 cm
        iu = ((U * len_u / 0.18) * ww).astype(int) % ww
        iv = ((Vv * len_v / 0.18) * wh).astype(int) % wh
        g = weave[iv, iu].mean(axis=2)
        g = g / max(float(g.mean()), 1e-3)
        col = col * np.clip(g, 0.4, 1.6)[..., None]
    else:
        g = 0.88 + 0.12 * np.sin(U * len_u * 2800) * np.sin(Vv * len_v * 2600)
        col = col * g[..., None]
    P3 = np.stack([U.ravel() * len_u, Vv.ravel() * len_v, np.zeros(U.size)], 1)
    var = fbm(P3, 6.0, 4, seed=seed).reshape(Hpx, Wpx)
    col = col * (0.75 + 0.5 * var)[..., None]
    rough = np.full((Hpx, Wpx), 0.62)
    gold = np.zeros((Hpx, Wpx))
    if "v0" in border_edges:
        gold = np.maximum(gold, temple_border(U, Vv * len_v, len_u))
    if "v1" in border_edges:
        gold = np.maximum(gold, temple_border(U, (1 - Vv) * len_v, len_u))
    if pallu_end:
        # the decorated end of the pallu: wide gold bands with a buta (mango) motif
        du = (1 - U) * len_u
        bands = ((du > 0.03) & (du < 0.05)) | ((du > 0.16) & (du < 0.175))
        cu = (du % 0.06) - 0.03
        cv = ((Vv * len_v) % 0.07) - 0.035
        buta = (np.sqrt((cu / 0.012) ** 2 + (cv / 0.018) ** 2) < 1.0) & (du > 0.06) & (du < 0.15)
        gold = np.maximum(gold, (bands | buta).astype(float))
    sheen = 0.75 + 0.5 * fbm(P3, 80.0, 2, seed=seed + 4).reshape(Hpx, Wpx)
    col = mix(col.reshape(-1, 3), (GOLD * 1.15)[None, :] * sheen.reshape(-1, 1), gold.reshape(-1) * 0.95).reshape(Hpx, Wpx, 3)
    rough = np.where(gold > 0.5, 0.35, rough)
    # dirt, old blood, faded patches, wet hem
    stain = smooth(0.62, 0.82, fbm(P3, 4.0, 4, seed=seed + 7)).reshape(Hpx, Wpx)
    col = mix(col.reshape(-1, 3), np.tile(BLOOD_DRY, (U.size, 1)), stain.reshape(-1) * 0.75).reshape(Hpx, Wpx, 3)
    dirt = smooth(0.25, 0.0, Vv) if "v0" in border_edges else np.zeros_like(Vv)
    col = col * (1.0 - 0.55 * dirt * (0.6 + 0.4 * var))[..., None]
    fade = smooth(0.55, 0.75, fbm(P3, 2.5, 3, seed=seed + 9)).reshape(Hpx, Wpx)
    col = mix(col.reshape(-1, 3), (col * 1.4 + 0.03).reshape(-1, 3), fade.reshape(-1) * 0.35).reshape(Hpx, Wpx, 3)
    return np.clip(col, 0, 1), rough


# ------------------------------------------------------------------------------------------------ small textures
def eye(size=256):
    """Spherical-UV eye: glowing red with a black slit pupil facing -Y (u = 0.75 front for our sphere UVs)."""
    u = (np.arange(size) + 0.5) / size
    v = (np.arange(size) + 0.5) / size
    U, Vv = np.meshgrid(u, v)
    lon = (U - 0.5) * 2 * np.pi
    lat = (0.5 - Vv) * np.pi
    d = np.sqrt(lon ** 2 + (lat * 1.0) ** 2)
    col = np.tile(np.array([0.85, 0.05, 0.02]), (size, size, 1))
    col = col * (0.6 + 0.4 * smooth(0.9, 0.2, d))[..., None]
    veins = 0.5 + 0.5 * np.sin(np.arctan2(lat, lon) * 23.0) * np.sin(d * 40.0)
    col = col * (0.85 + 0.15 * veins)[..., None]
    pupil = (np.abs(lon) < 0.06 * (1.0 - np.abs(lat) / 0.5)) & (np.abs(lat) < 0.45)
    col[pupil] = 0.0
    emit = col * smooth(1.4, 0.3, d)[..., None]
    return np.clip(col, 0, 1), np.clip(emit, 0, 1)


_DIGITS = {
    "0": ["111", "101", "101", "101", "111"], "1": ["010", "110", "010", "010", "111"],
    "2": ["111", "001", "111", "100", "111"], "3": ["111", "001", "111", "001", "111"],
    "4": ["101", "101", "111", "001", "001"], "5": ["111", "100", "111", "001", "111"],
    "6": ["111", "100", "111", "101", "111"], "7": ["111", "001", "010", "010", "010"],
    "8": ["111", "101", "111", "101", "111"], "9": ["111", "101", "111", "001", "111"],
}


def scale_tex(W=2048, Hh=128, length=0.61, wood=None):
    """The scale: wood grain (photo if given), centimetre ticks and numbers printed along the top face.
    u runs along the scale, v around its profile: the top face is v in [0.5, 0.625] (profile edge 4->5)."""
    u = (np.arange(W) + 0.5) / W
    v = (np.arange(Hh) + 0.5) / Hh
    U, Vv = np.meshgrid(u, v)
    if wood is not None:
        wh, ww = wood.shape[:2]
        iu = ((U * length / 0.25) * ww).astype(int) % ww
        iv = ((Vv * 0.05 / 0.25) * wh).astype(int) % wh
        col = wood[iv, iu] * np.array([1.05, 0.95, 0.8])
    else:
        grain = 0.5 + 0.5 * np.sin(U * 900 + 3 * np.sin(Vv * 20 + U * 40))
        col = np.array([0.62, 0.45, 0.26]) * (0.8 + 0.2 * grain)[..., None]
    col = col * (0.85 + 0.15 * np.sin(Vv * 6.28))[..., None]
    x_cm = U * length * 100.0 - 7.0                     # 0 cm sits just past the handle
    top = (Vv > 0.45) & (Vv < 0.95)                     # the printed face
    fr = np.abs(x_cm - np.round(x_cm))
    tick_len = np.where(fr < 0.04, 0.07, 0.0)
    tick_len = np.where((fr < 0.04) & (np.round(x_cm) % 5 == 0), 0.11, tick_len)
    tick_len = np.where((fr < 0.05) & (np.round(x_cm) % 10 == 0), 0.16, tick_len)
    ticks = top & (x_cm > -0.05) & (x_cm < 52.05) & ((Vv - 0.46) < tick_len) & (Vv > 0.46)
    ink = ticks.astype(float)
    # numbers every 5 cm
    gw = 0.0024                                            # glyph pixel width in u
    gh = 0.026                                             # glyph pixel height in v
    for cm in range(0, 51, 5):
        s = str(cm)
        cx = (cm + 7.0) / (length * 100.0)
        for k, ch in enumerate(s):
            gx0 = cx - len(s) * gw * 2 + k * gw * 4 + gw * 0.5
            for r, row in enumerate(_DIGITS[ch]):
                for c, bit in enumerate(row):
                    if bit == "1":
                        x0 = gx0 + c * gw
                        y0 = 0.80 - r * gh             # rows go down the face (top of the glyph furthest out)
                        m = (U >= x0) & (U < x0 + gw) & (Vv >= y0) & (Vv < y0 + gh)
                        ink = np.maximum(ink, m.astype(float))
    col = mix(col.reshape(-1, 3), np.array([0.05, 0.04, 0.03]), ink.reshape(-1) * 0.9).reshape(Hh, W, 3)
    # dark old blood near the end she hits with
    P3 = np.stack([U.ravel() * 3, Vv.ravel(), np.zeros(U.size)], 1)
    b = smooth(0.55, 0.75, fbm(P3, 9.0, 3, seed=40)).reshape(Hh, W) * smooth(0.55, 0.95, U)
    col = mix(col.reshape(-1, 3), np.tile(BLOOD, (U.size, 1)), b.reshape(-1) * 0.85).reshape(Hh, W, 3)
    return np.clip(col, 0, 1)
